            "expr": "histogram_quantile(0.95, sum(rate(cipherbox_republish_batch_duration_seconds_bucket[$__rate_interval])) by (le, tee_provider))",
            "legendFormat": "p95 {{ tee_provider }}",
            "refId": "B"
        },
        {
            "expr": "histogram_quantile(0.99, sum(rate(cipherbox_republish_batch_duration_seconds_bucket[$__rate_interval])) by (le, tee_provider))",
            "legendFormat": "p99 {{ tee_provider }}",
            "refId": "C"
        }
    ]
}

# 4. Kubo Health row + 3 panels
kubo_row = {
    "type": "row",
    "title": "Kubo Health",
    "gridPos": { "h": 1, "w": 24, "x": 0, "y": 0 },  # y will be set later
    "collapsed": False,
    "panels": []
}

kubo_peer_panel = {
    "type": "timeseries",
    "title": "Kubo Peer Connections",
    "gridPos": { "h": 6, "w": 8, "x": 0, "y": 0 },
    "datasource": DS,
    "fieldConfig": {
        "defaults": {
            "color": { "mode": "palette-classic" },
            "custom": {
                "lineWidth": 2,
                "fillOpacity": 20,
                "spanNulls": False,
                "drawStyle": "line",
                "pointSize": 5,
                "showPoints": "auto"
            }
        },
        "overrides": []
    },
    "options": duration_panel_options(),
    "targets": [
        {
            "expr": "libp2p_swarm_connections_opened_total - libp2p_swarm_connections_closed_total",
            "legendFormat": "Active connections",
            "refId": "A"
        },
        {
            "expr": "go_goroutines{job=\"kubo\"}",
            "legendFormat": "Goroutines (proxy)",
            "refId": "B"
        }
    ]
}

kubo_bandwidth_panel = {
    "type": "timeseries",
    "title": "Kubo Network Bandwidth",
    "gridPos": { "h": 6, "w": 8, "x": 8, "y": 0 },
    "datasource": DS,
    "fieldConfig": {
        "defaults": {
            "unit": "Bps",
            "color": { "mode": "palette-classic" },
            "custom": {
                "lineWidth": 2,
                "fillOpacity": 20,
                "spanNulls": False,
                "drawStyle": "line",
                "pointSize": 5,
                "showPoints": "auto"
            }
        },
        "overrides": [
            {
                "matcher": { "id": "byName", "options": "Outbound" },
                "properties": [{ "id": "color", "value": { "fixedColor": "blue", "mode": "fixed" } }]
            },
            {
                "matcher": { "id": "byName", "options": "Inbound" },
                "properties": [{ "id": "color", "value": { "fixedColor": "green", "mode": "fixed" } }]
            }
        ]
    },
    "options": duration_panel_options(),
    "targets": [
        {
            "expr": "rate(libp2p_network_out_bytes_total[$__rate_interval])",
            "legendFormat": "Outbound",
            "refId": "A"
        },
        {
            "expr": "rate(libp2p_network_in_bytes_total[$__rate_interval])",
            "legendFormat": "Inbound",
            "refId": "B"
        }
    ]
}

kubo_datastore_panel = {
    "type": "stat",
    "title": "Kubo Datastore / Memory",
    "gridPos": { "h": 6, "w": 8, "x": 16, "y": 0 },
    "datasource": DS,
    "fieldConfig": {
        "defaults": {
            "unit": "bytes",
            "thresholds": {
                "mode": "absolute",
                "steps": [
                    { "color": "green", "value": None },
                    { "color": "yellow", "value": 536870912 },
                    { "color": "red", "value": 1073741824 }
                ]
            },
            "color": { "mode": "thresholds" }
        },
        "overrides": []
    },
    "options": {
        "reduceOptions": { "calcs": ["lastNotNull"] },
        "colorMode": "value",
        "graphMode": "area",
        "justifyMode": "auto",
        "textMode": "auto",
        "wideLayout": True
    },
    "targets": [
        {
            "expr": "go_memstats_alloc_bytes{job=\"kubo\"}",
            "legendFormat": "Heap alloc",
            "refId": "A"
        }
    ]
}

# Now rebuild the panels array with insertions and y-shifts
# Step 1: Insert IPFS duration panels after File Operations panels (after y=13)
# Step 2: Insert IPNS duration panels after IPNS panels (after y=22 in original)
# Step 3: Insert TEE batch duration panel after TEE panels
# Step 4: Insert Kubo Health row+panels before Logs row

new_panels = []
y_offset = 0  # Accumulated y offset from insertions

for p in panels:
    orig_y = p['gridPos']['y']

    # After File Operations panels (y=6-13), insert IPFS duration panels
    if orig_y == 14 and y_offset == 0:
        # Insert IPFS duration panels at y=14
        ipfs_duration_panel['gridPos']['y'] = 14
        ipfs_error_panel['gridPos']['y'] = 14
        new_panels.append(ipfs_duration_panel)
        new_panels.append(ipfs_error_panel)
        y_offset += 8  # Shift everything after by 8

    # After IPNS panels (orig y=15-22, h=8 -> ends at 23), insert IPNS duration panels
    if orig_y == 23 and y_offset == 8:
        # Insert IPNS duration panels at 23+8=31
        ipns_duration_panel['gridPos']['y'] = 23 + y_offset
        ipns_source_panel['gridPos']['y'] = 23 + y_offset
        new_panels.append(ipns_duration_panel)
        new_panels.append(ipns_source_panel)
        y_offset += 8  # Now total offset is 16

    # After TEE panels, insert TEE batch duration panel
    # TEE section: row at y=23, panels at y=24-31 (the last panel ends at y=28+4=32)
    # In original coords, Authentication row is at y=32
    if orig_y == 32 and y_offset == 16:
        # Insert TEE batch duration at y=32+16=48, but we want it before Auth row
        # Actually: the last TEE panel was "Republish Schedule Status" at orig_y=28, h=4 -> ends at 32
        # So we insert at y=32+offset=48
        tee_duration_panel['gridPos']['y'] = 32 + y_offset
        new_panels.append(tee_duration_panel)
        y_offset += 8  # Now total offset is 24

    # Before Logs row, insert Kubo Health
    if orig_y == 58 and y_offset == 24:
        kubo_y = 58 + y_offset  # 82
        kubo_row['gridPos']['y'] = kubo_y
        kubo_peer_panel['gridPos']['y'] = kubo_y + 1
        kubo_bandwidth_panel['gridPos']['y'] = kubo_y + 1
        kubo_datastore_panel['gridPos']['y'] = kubo_y + 1
        new_panels.append(kubo_row)
        new_panels.append(kubo_peer_panel)
        new_panels.append(kubo_bandwidth_panel)
        new_panels.append(kubo_datastore_panel)
        y_offset += 7  # 1 row + 6 panel height; total offset now 31

    # Apply offset to original panel
    p_copy = json.loads(json.dumps(p))  # deep copy
    p_copy['gridPos']['y'] = orig_y + y_offset
    new_panels.append(p_copy)

dashboard['panels'] = new_panels

# Validate: no overlapping gridPos
# Check for panels with same y range and overlapping x range
for i, p1 in enumerate(new_panels):
    if p1['type'] == 'row':
        continue
    for j, p2 in enumerate(new_panels):
        if i >= j or p2['type'] == 'row':
            continue
        g1, g2 = p1['gridPos'], p2['gridPos']
        # Check vertical overlap
        y_overlap = g1['y'] < g2['y'] + g2['h'] and g2['y'] < g1['y'] + g1['h']
        # Check horizontal overlap
        x_overlap = g1['x'] < g2['x'] + g2['w'] and g2['x'] < g1['x'] + g1['w']
        if y_overlap and x_overlap:
            print(f"OVERLAP: panel '{p1.get('title', 'row')}' ({g1}) and '{p2.get('title', 'row')}' ({g2})")

# Print panel summary
for p in new_panels:
    title = p.get('title', '???')
    gp = p['gridPos']
    print(f"  y={gp['y']:3d}  h={gp['h']}  x={gp['x']:2d}  w={gp['w']:2d}  {title}")

with open('docker/grafana/dashboards/cipherbox-staging.json', 'w') as f:
    json.dump(dashboard, f, indent=2)
    f.write('\n')

print("\nDashboard updated successfully!")
print(f"Total panels: {len(new_panels)}")
PYEOF

